def test_exactly_the_unused_function_was_removed():
    found = {}
    for f in sorted(pathlib.Path("services").glob("*.py")):
        src = f.read_text().replace("\r\n", "\n")
        for n in ast.parse(src).body:
            if isinstance(n, ast.FunctionDef):
                found[n.name] = ast.get_source_segment(src, n).strip()
    assert "reconcile_warehouse_bins" not in found, "the unused function is still there"
    missing = sorted(EXPECTED.keys() - found.keys())
    assert not missing, f"used functions were deleted: {missing}"
    assert found.keys() == EXPECTED.keys()
    changed = [n for n in EXPECTED if found[n] != EXPECTED[n]]
    assert not changed, f"functions were changed: {changed}"
